#!/usr/bin/env python3
"""Evaluate native, JIT, or ONNX RSL-RL policies in a closed IsaacLab loop."""

from __future__ import annotations

import argparse
import atexit
import json
import math
import re
import subprocess
import sys
import time
from collections.abc import Mapping
from pathlib import Path
from typing import Any

from policy_evaluation_telemetry import (
    TELEMETRY_SIGNALS,
    ROA_ABLATION_MODES,
    roa_diagnostic_signals,
    capture_roa_diagnostics,
    DWAQ_DIAGNOSTIC_SIGNALS,
    capture_dwaq_diagnostics,
    BodyJitterTracker,
    JointLimitTracker,
    SignalLedger,
    metric_availability_report,
    record_complete_metric,
    required_signals_for_runner,
    telemetry_report,
)
from policy_evaluation_evidence import (
    EvaluationEvidenceError,
    EvaluationPublisher,
    build_scenario_contract,
    close_evaluation_resources,
    preflight_evaluation,
)

ORIGINAL_ARGV = tuple(sys.argv)
REPO_ROOT = Path(__file__).resolve().parents[3]

from isaaclab.app import AppLauncher

import cli_args  # isort: skip


parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--task", required=True, help="Exact registered training task")
parser.add_argument(
    "--agent",
    default="rsl_rl_cfg_entry_point",
    help="Agent configuration entry point",
)
parser.add_argument("--artifact_kind", choices=("native", "jit", "onnx"), required=True)
parser.add_argument("--artifact_path", required=True)
parser.add_argument("--artifact_sha256", required=True)
parser.add_argument("--candidate_id", required=True)
parser.add_argument("--checkpoint_sha256", required=True)
parser.add_argument("--scenario_id", required=True)
parser.add_argument("--scenario_overrides_json", default="{}")
parser.add_argument("--command_schedule_json", default="[]")
parser.add_argument("--duration_steps", type=int, required=True)
parser.add_argument("--executor_run_id")
parser.add_argument("--evaluation_id", required=True)
parser.add_argument("--result_path", required=True)
parser.add_argument("--run_id", required=True)
parser.add_argument("--run_identity_path", required=True)
parser.add_argument("--run_identity_file_sha256", required=True)
parser.add_argument("--video_path")
parser.add_argument("--no_video", action="store_true")
parser.add_argument("--allow_training_overlap", action="store_true")
parser.add_argument("--follow_robot_camera", action="store_true")
parser.add_argument(
    "--follow_camera_offset_json",
    default="[3.0, 3.0, 2.0]",
    help="World-frame camera eye offset from the selected robot",
)
parser.add_argument("--batch_id")
parser.add_argument("--effective_config_reference_json")
parser.add_argument("--scenario_evidence_reference_json")
parser.add_argument("--telemetry_path")
parser.add_argument("--telemetry_env_index", type=int, default=0)
parser.add_argument("--telemetry_stride", type=int, default=1)
parser.add_argument("--num_envs", type=int, default=16)
parser.add_argument("--seed", type=int, required=True)
parser.add_argument("--require_idle_gpu", action="store_true")
cli_args.add_rsl_rl_args(parser)
if "-h" in ORIGINAL_ARGV or "--help" in ORIGINAL_ARGV:
    parser.print_help()
    raise SystemExit(0)
AppLauncher.add_app_launcher_args(parser)
args_cli, hydra_args = parser.parse_known_args()
args_cli.enable_cameras = not args_cli.no_video


def _assert_gpu_idle(device: str | None) -> None:
    if not args_cli.require_idle_gpu or device is None or not device.startswith("cuda"):
        return
    gpu_index = device.split(":", 1)[1] if ":" in device else "0"
    check = subprocess.run(
        [
            "nvidia-smi",
            "-i",
            gpu_index,
            "--query-compute-apps=pid",
            "--format=csv,noheader,nounits",
        ],
        check=False,
        capture_output=True,
        text=True,
    )
    if check.returncode != 0:
        raise RuntimeError(
            f"cannot verify that GPU {gpu_index} is idle: {check.stderr.strip()}"
        )
    active_pids = [
        line.strip()
        for line in check.stdout.splitlines()
        if line.strip() and line.strip().isdigit()
    ]
    if active_pids:
        raise RuntimeError(
            f"GPU {gpu_index} is not idle; active compute PID(s): "
            f"{', '.join(active_pids)}"
        )


def _assert_executor_identity() -> None:
    if (
        args_cli.executor_run_id is not None
        and args_cli.executor_run_id != args_cli.run_id
    ):
        raise RuntimeError(
            "--executor_run_id must exactly match the approved --run_id"
        )


def _assert_resource_mode() -> None:
    if args_cli.require_idle_gpu and args_cli.allow_training_overlap:
        raise RuntimeError(
            "--require_idle_gpu and --allow_training_overlap are mutually exclusive"
        )
    if args_cli.allow_training_overlap:
        if args_cli.num_envs > 4:
            raise RuntimeError("training-overlap evaluation permits at most 4 environments")
        if args_cli.duration_steps > 2000:
            raise RuntimeError("training-overlap evaluation permits at most 2000 steps")
    if args_cli.no_video and args_cli.video_path:
        raise RuntimeError("--video_path must be omitted with --no_video")
    if not args_cli.no_video and not args_cli.video_path:
        raise RuntimeError("--video_path is required unless --no_video is used")
    if args_cli.telemetry_stride <= 0:
        raise RuntimeError("--telemetry_stride must be positive")
    if not 0 <= args_cli.telemetry_env_index < args_cli.num_envs:
        raise RuntimeError("--telemetry_env_index must select an existing environment")


try:
    _assert_executor_identity()
    _assert_resource_mode()
    scenario_contract = build_scenario_contract(
        scenario_id=args_cli.scenario_id,
        scenario_overrides_json=args_cli.scenario_overrides_json,
        command_schedule_json=args_cli.command_schedule_json,
        duration_steps=args_cli.duration_steps,
        num_envs=args_cli.num_envs,
        seed=args_cli.seed,
    )
    evaluation_plan = preflight_evaluation(
        repo_root=REPO_ROOT,
        task=args_cli.task,
        run_id=args_cli.run_id,
        evaluation_id=args_cli.evaluation_id,
        result_path=Path(args_cli.result_path),
        telemetry_path=Path(args_cli.telemetry_path) if args_cli.telemetry_path else None,
        video_path=Path(args_cli.video_path) if args_cli.video_path else None,
        checkpoint_path=Path(args_cli.checkpoint or ""),
        checkpoint_sha256=args_cli.checkpoint_sha256,
        artifact_kind=args_cli.artifact_kind,
        artifact_path=Path(args_cli.artifact_path),
        artifact_sha256=args_cli.artifact_sha256,
        run_identity_path=Path(args_cli.run_identity_path),
        run_identity_file_sha256=args_cli.run_identity_file_sha256,
        scenario_contract=scenario_contract,
        batch_id=args_cli.batch_id,
        effective_config=json.loads(args_cli.effective_config_reference_json) if args_cli.effective_config_reference_json else None,
        scenario_evidence=json.loads(args_cli.scenario_evidence_reference_json) if args_cli.scenario_evidence_reference_json else None,
    )
    _assert_gpu_idle(args_cli.device)
    evaluation_publisher = EvaluationPublisher(evaluation_plan)
    evaluation_publisher.__enter__()
except (RuntimeError, EvaluationEvidenceError) as exc:
    print(f"ERROR: {exc}", file=sys.stderr)
    raise SystemExit(2) from exc
atexit.register(evaluation_publisher.close)

sys.argv = [sys.argv[0]] + hydra_args
app_launcher = AppLauncher(args_cli)
simulation_app = app_launcher.app

import gymnasium as gym
import numpy as np
import torch

from rsl_rl.runners import (
    DistillationRunner,
    OnPolicyRunner,
    OnPolicyRunnerAmp,
    OnPolicyRunnerAmpDwaq,
    OnPolicyRunnerAmpROA,
    OnPolicyRunnerDwaq,
    OnPolicyRunnerROA,
)

from isaaclab.envs import (
    DirectMARLEnv,
    DirectMARLEnvCfg,
    DirectRLEnvCfg,
    ManagerBasedRLEnvCfg,
    multi_agent_to_single_agent,
)
from isaaclab_rl.rsl_rl import RslRlBaseRunnerCfg, RslRlVecEnvWrapper
from isaaclab_tasks.utils.hydra import hydra_task_config

import robot_lab.tasks  # noqa: F401


RUNNER_CLASSES = {
    "OnPolicyRunner": OnPolicyRunner,
    "DistillationRunner": DistillationRunner,
    "OnPolicyRunnerDwaq": OnPolicyRunnerDwaq,
    "OnPolicyRunnerAmp": OnPolicyRunnerAmp,
    "OnPolicyRunnerAmpDwaq": OnPolicyRunnerAmpDwaq,
    "OnPolicyRunnerROA": OnPolicyRunnerROA,
    "OnPolicyRunnerAmpROA": OnPolicyRunnerAmpROA,
}


def _scheduled_command(
    schedule: list[dict[str, Any]],
    step: int,
) -> list[float] | None:
    for segment in schedule:
        if segment["start_step"] <= step <= segment["end_step"]:
            return [float(value) for value in segment["command"]]
    return None


def _set_dotted(root: Any, dotted_path: str, value: Any) -> None:
    parts = dotted_path.split(".")
    if parts and parts[0] == "env":
        parts = parts[1:]
    if not parts:
        raise ValueError(f"invalid empty override path: {dotted_path}")
    current = root
    for part in parts[:-1]:
        if isinstance(current, dict):
            if part not in current:
                raise ValueError(f"override path does not exist: {dotted_path}")
            current = current[part]
        else:
            if not hasattr(current, part):
                raise ValueError(f"override path does not exist: {dotted_path}")
            current = getattr(current, part)
    leaf = parts[-1]
    if isinstance(current, dict):
        if leaf not in current:
            raise ValueError(f"override path does not exist: {dotted_path}")
        current[leaf] = value
    else:
        if not hasattr(current, leaf):
            raise ValueError(f"override path does not exist: {dotted_path}")
        setattr(current, leaf, value)


def _make_runner(
    env: RslRlVecEnvWrapper,
    agent_cfg: RslRlBaseRunnerCfg,
) -> Any:
    runner_class = RUNNER_CLASSES.get(agent_cfg.class_name)
    if runner_class is None:
        raise ValueError(f"unsupported runner class: {agent_cfg.class_name}")
    return runner_class(
        env,
        agent_cfg.to_dict(),
        log_dir=None,
        device=agent_cfg.device,
    )


def _policy_tensor(observations: Any) -> torch.Tensor:
    if isinstance(observations, Mapping):
        if "policy" not in observations:
            raise ValueError("observation mapping does not contain policy")
        tensor = observations["policy"]
    else:
        tensor = observations
    if not isinstance(tensor, torch.Tensor):
        raise ValueError("policy observation must be a torch.Tensor")
    if tensor.ndim > 2:
        tensor = tensor.flatten(1)
    return tensor


class ArtifactPolicy:
    """Run a deployment artifact and return actions on the simulation device."""

    def __init__(self, kind: str, path: Path, device: torch.device):
        self.kind = kind
        self.device = device
        self.jit = None
        self.ort_session = None
        self.ort_input = None
        if kind == "jit":
            self.jit = torch.jit.load(str(path), map_location=device).eval()
        elif kind == "onnx":
            import onnxruntime as ort

            self.ort_session = ort.InferenceSession(
                str(path),
                providers=["CPUExecutionProvider"],
            )
            self.ort_input = self.ort_session.get_inputs()[0].name

    def __call__(self, observations: Any) -> torch.Tensor:
        policy_input = _policy_tensor(observations)
        if self.kind == "jit":
            assert self.jit is not None
            output = self.jit(policy_input)
            if isinstance(output, (tuple, list)):
                output = output[0]
            if not isinstance(output, torch.Tensor):
                raise ValueError("JIT policy did not return a tensor")
            return output.to(self.device)
        if self.kind == "onnx":
            assert self.ort_session is not None and self.ort_input is not None
            output = self.ort_session.run(
                None,
                {self.ort_input: policy_input.detach().cpu().numpy()},
            )[0]
            return torch.from_numpy(np.asarray(output)).to(self.device)
        raise ValueError(f"unsupported deployment artifact kind: {self.kind}")


def _timeout_mask(extras: Any, dones: torch.Tensor) -> torch.Tensor:
    if isinstance(extras, dict):
        for key in ("time_outs", "timeouts"):
            value = extras.get(key)
            if isinstance(value, torch.Tensor) and value.shape == dones.shape:
                return value.to(device=dones.device, dtype=torch.bool)
    return torch.zeros_like(dones, dtype=torch.bool)


def _finalize_video(video_path: Path) -> str:
    candidates = sorted(
        video_path.parent.glob(f"{video_path.stem}*.mp4"),
        key=lambda path: path.stat().st_mtime_ns,
    )
    if not candidates:
        return ""
    source = candidates[-1]
    if source != video_path:
        source.replace(video_path)
    return str(video_path)


def _tensor_row(value: Any, env_index: int) -> list[float] | None:
    if not isinstance(value, torch.Tensor) or value.ndim == 0:
        return None
    if env_index >= value.shape[0]:
        return None
    row = [float(item) for item in value[env_index].detach().cpu().flatten().tolist()]
    if not row or not all(math.isfinite(item) for item in row):
        raise ValueError("tensor row is empty or non-finite")
    return row


def _required_tensor(
    value: Any,
    name: str,
    *,
    minimum_columns: int = 1,
) -> torch.Tensor:
    if not isinstance(value, torch.Tensor) or value.ndim < 2:
        raise TypeError(f"{name} must be a batched tensor")
    if value.shape[0] < 1 or value.shape[1] < minimum_columns:
        raise ValueError(f"{name} has an incompatible shape")
    if not torch.isfinite(value).all():
        raise ValueError(f"{name} contains non-finite values")
    return value


def _joint_limit_tensor(
    value: Any,
    name: str,
    *,
    environment_count: int,
    joint_count: int,
) -> torch.Tensor:
    tensor = _required_tensor(value, name, minimum_columns=joint_count)
    if tensor.shape[0] != environment_count or tensor.shape[1] != joint_count:
        raise ValueError(f"{name} shape does not match environments and joint_names")
    if torch.any(tensor <= 0.0):
        raise ValueError(f"{name} must contain only positive limits")
    return tensor


def _actuator_limit_tensor(
    robot: Any,
    attribute: str,
    name: str,
    *,
    environment_count: int,
    joint_count: int,
) -> torch.Tensor:
    joint_position = _required_tensor(
        robot.data.joint_pos,
        "joint_position",
        minimum_columns=joint_count,
    )
    resolved = torch.full_like(joint_position, float("nan"))
    assigned = torch.zeros(joint_count, dtype=torch.bool, device=resolved.device)
    for actuator_name, actuator in robot.actuators.items():
        raw_indices = actuator.joint_indices
        if isinstance(raw_indices, slice):
            indices = torch.arange(joint_count, device=resolved.device)[raw_indices]
        else:
            indices = torch.as_tensor(
                raw_indices,
                dtype=torch.long,
                device=resolved.device,
            ).flatten()
        if indices.numel() == 0:
            raise ValueError(f"actuator {actuator_name} has no joint indices")
        if torch.any(indices < 0) or torch.any(indices >= joint_count):
            raise ValueError(f"actuator {actuator_name} has invalid joint indices")
        if torch.any(assigned[indices]):
            raise ValueError(f"actuator {actuator_name} overlaps another actuator group")
        actuator_limits = _required_tensor(
            getattr(actuator, attribute),
            f"{name}:{actuator_name}",
            minimum_columns=int(indices.numel()),
        )
        if (
            actuator_limits.shape[0] != environment_count
            or actuator_limits.shape[1] != indices.numel()
        ):
            raise ValueError(f"{name}:{actuator_name} has an incompatible shape")
        resolved[:, indices] = actuator_limits
        assigned[indices] = True
    if not torch.all(assigned):
        missing = [
            str(robot.joint_names[index])
            for index in torch.nonzero(~assigned, as_tuple=False).flatten().tolist()
        ]
        raise ValueError(f"{name} missing actuator joints: {', '.join(missing)}")
    return _joint_limit_tensor(
        resolved,
        name,
        environment_count=environment_count,
        joint_count=joint_count,
    )


def _finite_scalar(value: Any, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be numeric")
    numeric = float(value)
    if not math.isfinite(numeric):
        raise ValueError(f"{name} must be finite")
    return numeric


def _joint_names(robot: Any) -> list[str]:
    names = [str(name) for name in getattr(robot, "joint_names", [])]
    if not names:
        raise ValueError("robot joint names are unavailable")
    return names


def _parse_camera_offset(raw: str) -> list[float]:
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ValueError("--follow_camera_offset_json must be valid JSON") from exc
    if (
        not isinstance(value, list)
        or len(value) != 3
        or any(isinstance(item, bool) or not isinstance(item, (int, float)) for item in value)
        or not all(np.isfinite(float(item)) for item in value)
    ):
        raise ValueError("camera offset must be three finite numbers")
    return [float(item) for item in value]


def _update_follow_camera(env: RslRlVecEnvWrapper, env_index: int, offset: list[float]) -> None:
    robot = env.unwrapped.scene["robot"]
    target = _tensor_row(robot.data.root_pos_w, env_index)
    if target is None or len(target) < 3:
        raise ValueError("robot root position is unavailable for camera follow")
    target = target[:3]
    eye = [target[index] + offset[index] for index in range(3)]
    env.unwrapped.sim.set_camera_view(eye, target)


def _prime_video_renderer(env: RslRlVecEnvWrapper) -> None:
    """Initialize the lazy RGB annotator before RecordVideo captures frame zero."""
    frame = env.unwrapped.render()
    if (
        not isinstance(frame, np.ndarray)
        or frame.ndim != 3
        or frame.shape[2] < 3
        or frame.size == 0
    ):
        raise ValueError("video renderer warmup did not return an RGB frame")


def _review_windows(
    peak_steps: dict[str, int | None],
    termination_first_steps: dict[str, int],
    duration_steps: int,
    step_dt: float,
) -> list[dict[str, Any]]:
    """Return bounded video windows around objective motion-risk evidence."""
    evidence_by_step: dict[int, list[str]] = {}
    for metric, step in peak_steps.items():
        if step is not None:
            evidence_by_step.setdefault(step, []).append(metric)
    for term_name, step in termination_first_steps.items():
        evidence_by_step.setdefault(step, []).append(
            f"termination:{term_name}"
        )
    windows: list[dict[str, Any]] = []
    radius = 30
    for step in sorted(evidence_by_step):
        start_step = max(0, step - radius)
        end_step = min(duration_steps - 1, step + radius)
        windows.append(
            {
                "start_step": start_step,
                "end_step": end_step,
                "start_seconds": start_step * step_dt,
                "end_seconds": (end_step + 1) * step_dt,
                "evidence": sorted(evidence_by_step[step]),
            }
        )
    return windows


def _evaluate(
    env_cfg: ManagerBasedRLEnvCfg | DirectRLEnvCfg | DirectMARLEnvCfg,
    agent_cfg: RslRlBaseRunnerCfg,
    publisher: EvaluationPublisher,
) -> None:
    """Run one authorized evaluation matrix cell and write bounded JSON."""
    if args_cli.duration_steps <= 0:
        raise ValueError("--duration_steps must be positive")
    if args_cli.num_envs <= 0:
        raise ValueError("--num_envs must be positive")

    agent_cfg = cli_args.update_rsl_rl_cfg(agent_cfg, args_cli)
    env_cfg.scene.num_envs = args_cli.num_envs
    env_cfg.seed = args_cli.seed
    env_cfg.sim.device = (
        args_cli.device if args_cli.device is not None else env_cfg.sim.device
    )
    command_schedule = evaluation_plan.scenario_contract["command_schedule"]
    roa_mode = evaluation_plan.scenario_contract["scenario_overrides"].get("evaluation.roa_mode")
    dwaq_mode = evaluation_plan.scenario_contract["scenario_overrides"].get("evaluation.dwaq_mode")
    diagnostic_signals = roa_diagnostic_signals(roa_mode) if roa_mode else ()
    if dwaq_mode is not None:
        diagnostic_signals = DWAQ_DIAGNOSTIC_SIGNALS
        if (agent_cfg.class_name != "OnPolicyRunnerDwaq" or args_cli.artifact_kind != "native"
                or evaluation_plan.telemetry_path is None):
            raise ValueError("DWAQ diagnostics require native OnPolicyRunnerDwaq and telemetry")
    if roa_mode is not None and (
        agent_cfg.class_name != "OnPolicyRunnerROA" or args_cli.artifact_kind != "native"
        or evaluation_plan.telemetry_path is None
    ):
        raise ValueError("ROA diagnostics require native OnPolicyRunnerROA and telemetry")
    for dotted_path, value in evaluation_plan.scenario_contract[
        "scenario_overrides"
    ].items():
        if dotted_path in ("evaluation.roa_mode", "evaluation.dwaq_mode"):
            continue
        _set_dotted(env_cfg, dotted_path, value)
    if command_schedule:
        command_cfg = env_cfg.commands.base_velocity
        command_cfg.resampling_time_range = (1.0e9, 1.0e9)
        if hasattr(command_cfg, "heading_command"):
            command_cfg.heading_command = False
        if hasattr(command_cfg, "rel_standing_envs"):
            command_cfg.rel_standing_envs = 0.0

    checkpoint_path = Path(evaluation_plan.checkpoint["path"])
    artifact_path = Path(evaluation_plan.artifact["path"])
    result_path = evaluation_plan.result_path
    video_path = (
        publisher.video_work_path if evaluation_plan.video_path is not None else None
    )
    telemetry_path = evaluation_plan.telemetry_path

    raw_env = gym.make(
        args_cli.task,
        cfg=env_cfg,
        render_mode="rgb_array" if video_path is not None else None,
    )
    if isinstance(raw_env.unwrapped, DirectMARLEnv):
        raw_env = multi_agent_to_single_agent(raw_env)
    if video_path is not None:
        raw_env = gym.wrappers.RecordVideo(
            raw_env,
            video_folder=str(video_path.parent),
            step_trigger=lambda step: step == 0,
            video_length=args_cli.duration_steps,
            name_prefix=video_path.stem,
            disable_logger=True,
        )
    env = RslRlVecEnvWrapper(raw_env, clip_actions=agent_cfg.clip_actions)

    runner_name = agent_cfg.class_name
    runner = _make_runner(env, agent_cfg)
    runner.load(str(checkpoint_path))
    native_policy = runner.get_inference_policy(device=env.unwrapped.device)
    try:
        policy_module = runner.alg.policy
    except AttributeError:
        policy_module = runner.alg.actor_critic

    artifact_policy = None
    if args_cli.artifact_kind != "native":
        artifact_policy = ArtifactPolicy(
            args_cli.artifact_kind,
            artifact_path,
            torch.device(env.unwrapped.device),
        )

    command_term = None
    if command_schedule:
        command_term = env.unwrapped.command_manager.get_term("base_velocity")
        if not hasattr(command_term, "vel_command_b"):
            raise ValueError(
                "base_velocity command term does not support deterministic scheduling"
            )
    observations = env.get_observations()
    camera_offset = _parse_camera_offset(args_cli.follow_camera_offset_json)
    if args_cli.follow_robot_camera:
        _update_follow_camera(env, args_cli.telemetry_env_index, camera_offset)
    if video_path is not None:
        _prime_video_renderer(env)
    previous_actions: torch.Tensor | None = None
    robot = env.unwrapped.scene["robot"]
    roa_diagnostics = None
    dwaq_diagnostics = None
    if roa_mode is not None or dwaq_mode is not None:
        velocity_scale = env_cfg.observations.critic.base_lin_vel.scale
        velocity_scale = 1.0 if velocity_scale is None else velocity_scale
        diagnostics = {
            "controller": roa_mode or dwaq_mode, "sampling_phase": "pre_action", "velocity_units": "m/s",
            "velocity_observation_scale": torch.as_tensor(velocity_scale).reshape(-1).tolist(),
        }
        if roa_mode is not None:
            roa_diagnostics = diagnostics
        else:
            dwaq_diagnostics = diagnostics
    body_jitter_segments = command_schedule or [
        {
            "start_step": 0,
            "end_step": args_cli.duration_steps - 1,
            "command": None,
        }
    ]
    body_jitter_tracker = BodyJitterTracker(
        step_dt_seconds=float(env.unwrapped.step_dt),
        command_segments=body_jitter_segments,
    )
    telemetry_samples: list[dict[str, Any]] = []
    telemetry_joint_names: list[str] = []
    telemetry_joint_effort_limits: list[float] = []
    telemetry_joint_velocity_limits: list[float] = []
    telemetry_expected_samples = (
        args_cli.duration_steps + args_cli.telemetry_stride - 1
    ) // args_cli.telemetry_stride
    telemetry_ledger = None
    if telemetry_path is not None:
        telemetry_expected_counts = {
            name: telemetry_expected_samples for name in TELEMETRY_SIGNALS
        }
        for name in (
            "joint_names",
            "joint_effort_limits",
            "joint_velocity_limits",
        ):
            telemetry_expected_counts[name] = 1
        telemetry_ledger = SignalLedger(
            {**telemetry_expected_counts, **{name: telemetry_expected_samples for name in diagnostic_signals}},
            required_signals=required_signals_for_runner(runner_name) | frozenset(diagnostic_signals),
        )
    metric_input_names = (
        "command",
        "root_linear_velocity_b",
        "root_angular_velocity_b",
        "projected_gravity_b",
        "joint_velocity",
        "applied_torque",
    )
    metric_expected_counts = {
        name: args_cli.duration_steps for name in metric_input_names
    }
    for name in (
        "joint_names",
        "joint_effort_limits",
        "joint_velocity_limits",
    ):
        metric_expected_counts[name] = 1
    metric_ledger = SignalLedger(
        metric_expected_counts,
        required_signals=metric_expected_counts,
    )
    metric_joint_names = metric_ledger.capture("joint_names", lambda: _joint_names(robot))
    joint_count = len(metric_joint_names) if metric_joint_names is not None else 0
    metric_joint_effort_limits = metric_ledger.capture(
        "joint_effort_limits",
        lambda: _actuator_limit_tensor(
            robot,
            "effort_limit",
            "joint_effort_limits",
            environment_count=args_cli.num_envs,
            joint_count=joint_count,
        ),
    )
    metric_joint_velocity_limits = metric_ledger.capture(
        "joint_velocity_limits",
        lambda: _actuator_limit_tensor(
            robot,
            "velocity_limit",
            "joint_velocity_limits",
            environment_count=args_cli.num_envs,
            joint_count=joint_count,
        ),
    )
    joint_limit_tracker = None
    if (
        metric_joint_names is not None
        and metric_joint_effort_limits is not None
        and metric_joint_velocity_limits is not None
    ):
        joint_limit_tracker = JointLimitTracker(
            metric_joint_names,
            metric_joint_effort_limits.detach().cpu().tolist(),
            metric_joint_velocity_limits.detach().cpu().tolist(),
        )
    if telemetry_ledger is not None:
        names = telemetry_ledger.capture(
            "joint_names",
            lambda: list(metric_joint_names) if metric_joint_names is not None else None,
        )
        if names is not None:
            telemetry_joint_names = names
        effort_limits = telemetry_ledger.capture(
            "joint_effort_limits",
            lambda: _tensor_row(metric_joint_effort_limits, args_cli.telemetry_env_index),
        )
        if effort_limits is not None:
            telemetry_joint_effort_limits = effort_limits
        velocity_limits = telemetry_ledger.capture(
            "joint_velocity_limits",
            lambda: _tensor_row(
                metric_joint_velocity_limits, args_cli.telemetry_env_index
            ),
        )
        if velocity_limits is not None:
            telemetry_joint_velocity_limits = velocity_limits
    reward_sum = 0.0
    sample_count = 0
    termination_count = 0
    timeout_count = 0
    termination_term_counts: dict[str, int] = {}
    termination_manager = getattr(env.unwrapped, "termination_manager", None)
    termination_term_names = (
        tuple(termination_manager.active_terms)
        if termination_manager is not None
        else ()
    )
    tracking_xy_sq_sum = 0.0
    tracking_yaw_sq_sum = 0.0
    tracking_samples = 0
    tilt_sq_sum = 0.0
    tilt_samples = 0
    max_tilt = 0.0
    action_rate_sq_sum = 0.0
    action_rate_samples = 0
    max_abs_action = 0.0
    max_abs_joint_velocity = 0.0
    max_abs_applied_torque = 0.0
    max_abs_action_error = 0.0
    peak_steps: dict[str, int | None] = {
        "max_abs_action": None,
        "max_abs_action_error": None,
        "max_abs_applied_torque": None,
        "max_abs_joint_velocity": None,
        "max_joint_effort_utilization": None,
        "max_joint_velocity_utilization": None,
        "max_tilt": None,
    }
    termination_first_steps: dict[str, int] = {}
    start_time = time.monotonic()

    for step in range(args_cli.duration_steps):
        if args_cli.follow_robot_camera:
            _update_follow_camera(env, args_cli.telemetry_env_index, camera_offset)
        active_scheduled_command = _scheduled_command(command_schedule, step)
        if active_scheduled_command is not None:
            assert command_term is not None
            command_term.vel_command_b[:] = torch.tensor(
                active_scheduled_command,
                device=env.unwrapped.device,
                dtype=command_term.vel_command_b.dtype,
            )
            observations = env.get_observations()
        with torch.inference_mode():
            roa_snapshot = None
            dwaq_snapshot = None
            if roa_mode is not None:
                roa_snapshot = capture_roa_diagnostics(
                    policy_module, observations, robot.data.root_lin_vel_b, velocity_scale,
                    include_ablations=roa_mode in ROA_ABLATION_MODES,
                )
                native_actions = roa_snapshot[f"roa_{roa_mode}_action"]
            elif dwaq_mode is not None:
                dwaq_snapshot = capture_dwaq_diagnostics(
                    policy_module, observations, robot.data.root_lin_vel_b, velocity_scale,
                )
                native_actions = dwaq_snapshot[f"dwaq_{dwaq_mode}_action"]
            else:
                native_actions = native_policy(observations)
            if artifact_policy is None:
                actions = native_actions
            else:
                actions = artifact_policy(observations)
                error = float(
                    torch.max(torch.abs(native_actions - actions)).item()
                )
                if error > max_abs_action_error or peak_steps[
                    "max_abs_action_error"
                ] is None:
                    max_abs_action_error = error
                    peak_steps["max_abs_action_error"] = step
            if not torch.isfinite(actions).all():
                raise FloatingPointError("policy produced non-finite actions")
            observations, rewards, dones, extras = env.step(actions)
            if hasattr(policy_module, "reset"):
                policy_module.reset(dones)

        rewards_tensor = torch.as_tensor(rewards)
        dones_tensor = torch.as_tensor(dones, dtype=torch.bool)
        timeouts = _timeout_mask(extras, dones_tensor)
        terminations = dones_tensor & ~timeouts
        reward_sum += float(rewards_tensor.sum().item())
        sample_count += int(rewards_tensor.numel())
        termination_count += int(terminations.sum().item())
        timeout_count += int(timeouts.sum().item())
        for term_name in termination_term_names:
            term_value = termination_manager.get_term(term_name)
            term_count = int(term_value.sum().item())
            termination_term_counts[term_name] = (
                termination_term_counts.get(term_name, 0)
                + term_count
            )
            if term_count and term_name not in termination_first_steps:
                termination_first_steps[term_name] = step
        current_max_action = float(torch.max(torch.abs(actions)).item())
        if (
            current_max_action > max_abs_action
            or peak_steps["max_abs_action"] is None
        ):
            max_abs_action = current_max_action
            peak_steps["max_abs_action"] = step
        if previous_actions is not None:
            delta = actions - previous_actions
            action_rate_sq_sum += float(torch.square(delta).sum().item())
            action_rate_samples += int(delta.numel())
        previous_actions = actions.detach().clone()

        command = metric_ledger.capture(
            "command",
            lambda: _required_tensor(
                env.unwrapped.command_manager.get_command("base_velocity")
                if active_scheduled_command is None
                else torch.tensor(
                    active_scheduled_command,
                    device=actions.device,
                    dtype=actions.dtype,
                ).expand(actions.shape[0], -1),
                "command",
                minimum_columns=3,
            ),
        )
        root_linear_velocity = metric_ledger.capture(
            "root_linear_velocity_b",
            lambda: _required_tensor(
                env.unwrapped.scene["robot"].data.root_lin_vel_b,
                "root_linear_velocity_b",
                minimum_columns=2,
            ),
        )
        root_angular_velocity = metric_ledger.capture(
            "root_angular_velocity_b",
            lambda: _required_tensor(
                env.unwrapped.scene["robot"].data.root_ang_vel_b,
                "root_angular_velocity_b",
                minimum_columns=3,
            ),
        )
        projected_gravity = metric_ledger.capture(
            "projected_gravity_b",
            lambda: _required_tensor(
                env.unwrapped.scene["robot"].data.projected_gravity_b,
                "projected_gravity_b",
                minimum_columns=2,
            ),
        )
        joint_velocity = metric_ledger.capture(
            "joint_velocity",
            lambda: _required_tensor(
                env.unwrapped.scene["robot"].data.joint_vel,
                "joint_velocity",
            ),
        )
        applied_torque = metric_ledger.capture(
            "applied_torque",
            lambda: _required_tensor(
                env.unwrapped.scene["robot"].data.applied_torque,
                "applied_torque",
            ),
        )

        if projected_gravity is not None:
            gravity_xy = projected_gravity[:, :2]
            tilt = torch.linalg.vector_norm(gravity_xy, dim=1)
            tilt_sq_sum += float(torch.square(tilt).sum().item())
            tilt_samples += int(tilt.numel())
            current_max_tilt = float(torch.max(tilt).item())
            if (
                current_max_tilt > max_tilt
                or peak_steps["max_tilt"] is None
            ):
                max_tilt = current_max_tilt
                peak_steps["max_tilt"] = step
        if joint_velocity is not None:
            current_max_joint_velocity = float(torch.max(torch.abs(joint_velocity)).item())
            if (
                current_max_joint_velocity > max_abs_joint_velocity
                or peak_steps["max_abs_joint_velocity"] is None
            ):
                max_abs_joint_velocity = current_max_joint_velocity
                peak_steps["max_abs_joint_velocity"] = step
        if applied_torque is not None:
            current_max_applied_torque = float(torch.max(torch.abs(applied_torque)).item())
            if (
                current_max_applied_torque > max_abs_applied_torque
                or peak_steps["max_abs_applied_torque"] is None
            ):
                max_abs_applied_torque = current_max_applied_torque
                peak_steps["max_abs_applied_torque"] = step
        if (
            joint_limit_tracker is not None
            and joint_velocity is not None
            and applied_torque is not None
        ):
            joint_limit_tracker.observe(
                applied_torque.detach().cpu().tolist(),
                joint_velocity.detach().cpu().tolist(),
                step=step,
            )

        if (
            command is not None
            and root_linear_velocity is not None
            and root_angular_velocity is not None
        ):
            xy_error = command[:, :2] - root_linear_velocity[:, :2]
            yaw_error = command[:, 2] - root_angular_velocity[:, 2]
            tracking_xy_sq_sum += float(torch.square(xy_error).sum().item())
            tracking_yaw_sq_sum += float(torch.square(yaw_error).sum().item())
            tracking_samples += int(command.shape[0])
        if root_linear_velocity is not None and root_angular_velocity is not None:
            body_jitter_tracker.observe(
                root_linear_velocity.detach().cpu().tolist(),
                root_angular_velocity.detach().cpu().tolist(),
                dones_tensor.detach().cpu().tolist(),
                step=step,
            )

        if telemetry_ledger is not None and step % args_cli.telemetry_stride == 0:
            env_index = args_cli.telemetry_env_index
            sample = {
                "step": step,
                "sim_time_seconds": step * float(env.unwrapped.step_dt),
                "command": telemetry_ledger.capture(
                    "command", lambda: _tensor_row(command, env_index)
                ),
                "reward": telemetry_ledger.capture(
                    "reward",
                    lambda: _finite_scalar(
                        rewards_tensor[env_index].item(), "reward"
                    ),
                ),
                "done": telemetry_ledger.capture(
                    "done", lambda: bool(dones_tensor[env_index].item())
                ),
                "timeout": telemetry_ledger.capture(
                    "timeout", lambda: bool(timeouts[env_index].item())
                ),
                "root_position_w": telemetry_ledger.capture(
                    "root_position_w",
                    lambda: _tensor_row(
                        env.unwrapped.scene["robot"].data.root_pos_w, env_index
                    ),
                ),
                "root_quaternion_w": telemetry_ledger.capture(
                    "root_quaternion_w",
                    lambda: _tensor_row(
                        env.unwrapped.scene["robot"].data.root_quat_w, env_index
                    ),
                ),
                "root_linear_velocity_b": telemetry_ledger.capture(
                    "root_linear_velocity_b",
                    lambda: _tensor_row(
                        env.unwrapped.scene["robot"].data.root_lin_vel_b, env_index
                    ),
                ),
                "root_angular_velocity_b": telemetry_ledger.capture(
                    "root_angular_velocity_b",
                    lambda: _tensor_row(
                        env.unwrapped.scene["robot"].data.root_ang_vel_b, env_index
                    ),
                ),
                "projected_gravity_b": telemetry_ledger.capture(
                    "projected_gravity_b",
                    lambda: _tensor_row(
                        env.unwrapped.scene["robot"].data.projected_gravity_b,
                        env_index,
                    ),
                ),
                "joint_position": telemetry_ledger.capture(
                    "joint_position",
                    lambda: _tensor_row(
                        env.unwrapped.scene["robot"].data.joint_pos, env_index
                    ),
                ),
                "joint_velocity": telemetry_ledger.capture(
                    "joint_velocity",
                    lambda: _tensor_row(
                        env.unwrapped.scene["robot"].data.joint_vel, env_index
                    ),
                ),
                "applied_torque": telemetry_ledger.capture(
                    "applied_torque",
                    lambda: _tensor_row(
                        env.unwrapped.scene["robot"].data.applied_torque, env_index
                    ),
                ),
                "action": telemetry_ledger.capture(
                    "action", lambda: _tensor_row(actions, env_index)
                ),
            }
            if roa_snapshot is not None:
                for name in diagnostic_signals:
                    sample[name] = telemetry_ledger.capture(
                        name, lambda name=name: _tensor_row(roa_snapshot[name], env_index)
                    )
            if dwaq_snapshot is not None:
                for name in diagnostic_signals:
                    sample[name] = telemetry_ledger.capture(
                        name, lambda name=name: _tensor_row(dwaq_snapshot[name], env_index)
                    )
            telemetry_samples.append(sample)

    elapsed = max(time.monotonic() - start_time, 1e-12)
    simulated_seconds = (
        args_cli.duration_steps * float(env.unwrapped.step_dt)
    )
    metric_signal_report = metric_ledger.report()["signals"]
    joint_limit_evidence = (
        joint_limit_tracker.report() if joint_limit_tracker is not None else None
    )
    body_jitter_evidence = body_jitter_tracker.report()
    if joint_limit_evidence is not None:
        peak_steps.update(joint_limit_evidence["peak_steps"])
    peak_steps.update(body_jitter_evidence["peak_steps"])

    metric_availability = metric_availability_report(
        metric_signal_report,
        {
            "tracking_xy_rmse": ("command", "root_linear_velocity_b"),
            "tracking_yaw_rmse": ("command", "root_angular_velocity_b"),
            "tilt_rms": ("projected_gravity_b",),
            "max_tilt": ("projected_gravity_b",),
            "body_roll_pitch_angular_velocity_rms": (
                "root_angular_velocity_b",
            ),
            "body_roll_pitch_angular_velocity_p95": (
                "root_angular_velocity_b",
            ),
            "body_vertical_velocity_rms": ("root_linear_velocity_b",),
            "body_vertical_velocity_p95": ("root_linear_velocity_b",),
            "body_roll_pitch_angular_acceleration_rms": (
                "root_angular_velocity_b",
            ),
            "body_roll_pitch_angular_acceleration_p95": (
                "root_angular_velocity_b",
            ),
            "body_vertical_acceleration_rms": ("root_linear_velocity_b",),
            "body_vertical_acceleration_p95": ("root_linear_velocity_b",),
            "max_abs_joint_velocity": ("joint_velocity",),
            "max_abs_applied_torque": ("applied_torque",),
            "max_joint_effort_utilization": (
                "joint_names",
                "joint_effort_limits",
                "applied_torque",
            ),
            "max_joint_velocity_utilization": (
                "joint_names",
                "joint_velocity_limits",
                "joint_velocity",
            ),
            "joint_effort_limit_violation_rate": (
                "joint_names",
                "joint_effort_limits",
                "applied_torque",
            ),
            "joint_velocity_limit_violation_rate": (
                "joint_names",
                "joint_velocity_limits",
                "joint_velocity",
            ),
        },
    )
    metrics: dict[str, float] = {
        "mean_reward": reward_sum / max(sample_count, 1),
        "termination_rate": termination_count / max(sample_count, 1),
        "timeout_rate": timeout_count / max(sample_count, 1),
        "max_abs_action": max_abs_action,
        "action_rate_rms": (
            action_rate_sq_sum / max(action_rate_samples, 1)
        )
        ** 0.5,
        "max_abs_action_error": max_abs_action_error,
        "real_time_factor": simulated_seconds / elapsed,
    }
    record_complete_metric(
        metrics,
        metric_availability,
        "tracking_xy_rmse",
        lambda: (tracking_xy_sq_sum / (tracking_samples * 2)) ** 0.5,
    )
    record_complete_metric(
        metrics,
        metric_availability,
        "tracking_yaw_rmse",
        lambda: (tracking_yaw_sq_sum / tracking_samples) ** 0.5,
    )
    record_complete_metric(
        metrics,
        metric_availability,
        "tilt_rms",
        lambda: (tilt_sq_sum / tilt_samples) ** 0.5,
    )
    record_complete_metric(
        metrics, metric_availability, "max_tilt", lambda: max_tilt
    )
    for metric_name, metric_value in body_jitter_evidence["metrics"].items():
        if metric_value is None:
            availability = metric_availability[metric_name]
            availability["available"] = False
            availability["complete"] = False
            availability["partial"] = True
            availability["errors"]["derived"] = (
                "insufficient consecutive samples after transition exclusions"
            )
            continue
        record_complete_metric(
            metrics,
            metric_availability,
            metric_name,
            lambda value=metric_value: value,
        )
    record_complete_metric(
        metrics,
        metric_availability,
        "max_abs_joint_velocity",
        lambda: max_abs_joint_velocity,
    )
    record_complete_metric(
        metrics,
        metric_availability,
        "max_abs_applied_torque",
        lambda: max_abs_applied_torque,
    )
    for metric_name in (
        "max_joint_effort_utilization",
        "max_joint_velocity_utilization",
        "joint_effort_limit_violation_rate",
        "joint_velocity_limit_violation_rate",
    ):
        record_complete_metric(
            metrics,
            metric_availability,
            metric_name,
            lambda name=metric_name: joint_limit_evidence["metrics"][name],
        )
    for term_name, count in termination_term_counts.items():
        normalized_name = re.sub(r"[^a-z0-9]+", "_", term_name.lower()).strip(
            "_"
        )
        metric_value = count / max(sample_count, 1)
        metrics[f"termination_term_{normalized_name}_rate"] = metric_value
        if normalized_name == "illegal_contact":
            metrics["illegal_contact_rate"] = metric_value

    step_dt = float(env.unwrapped.step_dt)
    env.close()
    recorded_video = _finalize_video(video_path) if video_path is not None else ""
    telemetry_evidence = telemetry_report(
        requested=telemetry_path is not None,
        runner=runner_name,
        ledger=telemetry_ledger,
        additional_required_signals=diagnostic_signals,
    )
    evaluation_binding = {
        "task": evaluation_plan.task,
        "run_id": evaluation_plan.run_id,
        "evaluation_id": evaluation_plan.evaluation_id,
        "candidate_id": args_cli.candidate_id,
        "runner": runner_name,
    }
    resource_mode = {
        "training_overlap": bool(args_cli.allow_training_overlap),
        "idle_gpu_required": bool(args_cli.require_idle_gpu),
        "device": str(env_cfg.sim.device),
        "num_envs": args_cli.num_envs,
        "video_requested": evaluation_plan.video_path is not None,
        "telemetry_requested": telemetry_path is not None,
        "telemetry_env_index": args_cli.telemetry_env_index,
        "telemetry_stride": args_cli.telemetry_stride,
        "follow_robot_camera": bool(args_cli.follow_robot_camera),
    }
    inputs = {
        "checkpoint": evaluation_plan.checkpoint,
        "artifact": {
            "kind": evaluation_plan.artifact_kind,
            **evaluation_plan.artifact,
        },
        "run_identity": evaluation_plan.run_identity,
        "scenario": {
            "contract": evaluation_plan.scenario_contract,
            "sha256": evaluation_plan.scenario_sha256,
        },
        "resource_mode": resource_mode,
    }
    if evaluation_plan.batch_id is not None:
        evaluation_binding["batch_id"] = evaluation_plan.batch_id
        inputs["effective_config"] = evaluation_plan.effective_config
        inputs["scenario_evidence"] = evaluation_plan.scenario_evidence
    telemetry = None
    if telemetry_path is not None:
        telemetry = {
            "version": 4 if evaluation_plan.batch_id else 3,
            "evaluation": evaluation_binding,
            "inputs": inputs,
            "environment_index": args_cli.telemetry_env_index,
            "stride": args_cli.telemetry_stride,
            "step_dt_seconds": step_dt,
            "joint_names": telemetry_joint_names,
            "joint_effort_limits": telemetry_joint_effort_limits,
            "joint_velocity_limits": telemetry_joint_velocity_limits,
            **telemetry_evidence,
            "samples": telemetry_samples,
        }
        if roa_diagnostics is not None:
            telemetry["roa_diagnostics"] = roa_diagnostics
        if dwaq_diagnostics is not None:
            telemetry["dwaq_diagnostics"] = dwaq_diagnostics
    result = {
        "version": 3 if evaluation_plan.batch_id else 2,
        "layout_version": 2 if evaluation_plan.batch_id else 1,
        "run_id": args_cli.run_id,
        "status": "completed",
        "evaluation": evaluation_binding,
        "inputs": inputs,
        "candidate_id": args_cli.candidate_id,
        "runner": runner_name,
        "artifact": args_cli.artifact_kind,
        "scenario_id": args_cli.scenario_id,
        "seed": args_cli.seed,
        "duration_steps": args_cli.duration_steps,
        "checkpoint_path": str(checkpoint_path),
        "checkpoint_sha256": evaluation_plan.checkpoint["sha256"],
        "artifact_path": str(artifact_path),
        "artifact_sha256": evaluation_plan.artifact["sha256"],
        "run_identity_sha256": evaluation_plan.run_identity["identity_sha256"],
        "scenario_sha256": evaluation_plan.scenario_sha256,
        "video_path": (
            str(evaluation_plan.video_path)
            if evaluation_plan.video_path is not None
            else ""
        ),
        "telemetry_path": str(telemetry_path) if telemetry_path is not None else "",
        "telemetry_status": telemetry_evidence["telemetry_status"],
        "missing_required_signals": telemetry_evidence[
            "missing_required_signals"
        ],
        "telemetry_required_for_complete_assessment": telemetry_evidence[
            "telemetry_required_for_complete_assessment"
        ],
        "telemetry": telemetry_evidence,
        "training_overlap": bool(args_cli.allow_training_overlap),
        "metrics": metrics,
        "metric_availability": metric_availability,
        "joint_limit_evidence": joint_limit_evidence,
        "body_jitter_evidence": body_jitter_evidence,
        "motion_evidence": {
            "step_dt_seconds": step_dt,
            "peak_steps": peak_steps,
            "termination_first_steps": termination_first_steps,
            "review_windows": _review_windows(
                peak_steps,
                termination_first_steps,
                args_cli.duration_steps,
                step_dt,
            ),
        },
    }
    if roa_diagnostics is not None:
        result["roa_diagnostics"] = roa_diagnostics
    if dwaq_diagnostics is not None:
        result["dwaq_diagnostics"] = dwaq_diagnostics
    publisher.publish(
        result,
        telemetry=telemetry,
        video_source=Path(recorded_video) if recorded_video else None,
    )
    print(f"[INFO] Evaluation result: {result_path}")


@hydra_task_config(args_cli.task, args_cli.agent)
def main(
    env_cfg: ManagerBasedRLEnvCfg | DirectRLEnvCfg | DirectMARLEnvCfg,
    agent_cfg: RslRlBaseRunnerCfg,
) -> None:
    """Run one authorized evaluation matrix cell and publish bound evidence."""
    _evaluate(env_cfg, agent_cfg, evaluation_publisher)


if __name__ == "__main__":
    try:
        main()
    finally:
        close_evaluation_resources(evaluation_publisher, simulation_app)

#!/usr/bin/env python3
"""Validate and exclusively publish source-bound policy-evaluation evidence."""

from __future__ import annotations

import gzip
import hashlib
import sys
import json
import math
import os
import re
import shutil
from dataclasses import dataclass
from pathlib import Path
from typing import Any


SKILL_SCRIPTS = Path(__file__).resolve().parents[3] / ".agents/skills/monitor-tune-isaaclab-training/scripts"
sys.path.insert(0, str(SKILL_SCRIPTS))
from evidence_provenance import require_source_path, validate_provenance


SAFE_IDENTIFIER_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$")
SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
SCENARIO_FIELDS = {
    "scenario_id",
    "scenario_overrides",
    "command_schedule",
    "duration_steps",
    "num_envs",
    "seed",
}


class EvaluationEvidenceError(ValueError):
    """Raised when evaluation evidence is unsafe, conflicting, or incomplete."""


def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _validate_identifier(name: str, value: Any) -> str:
    if not isinstance(value, str) or not SAFE_IDENTIFIER_RE.fullmatch(value):
        raise EvaluationEvidenceError(
            f"{name} must be a safe ASCII identifier (letters, digits, '.', '_', '-')"
        )
    return value


def _validate_sha256(name: str, value: Any) -> str:
    if not isinstance(value, str) or not SHA256_RE.fullmatch(value):
        raise EvaluationEvidenceError(f"{name} must be a lowercase SHA-256")
    return value


def _reject_unsafe_path(path: Path, *, label: str) -> None:
    if not path.is_absolute() or ".." in path.parts:
        raise EvaluationEvidenceError(
            f"{label} must be an absolute path without traversal"
        )
    current = Path(path.anchor)
    for component in path.parts[1:]:
        current /= component
        if current.is_symlink():
            raise EvaluationEvidenceError(
                f"{label} contains a symlinked path component: {current}"
            )


def _require_regular_file(
    path: Path,
    *,
    label: str,
    expected_sha256: str | None = None,
) -> dict[str, str]:
    _reject_unsafe_path(path, label=label)
    if not path.is_file():
        raise EvaluationEvidenceError(f"{label} is not an existing regular file")
    actual_sha256 = sha256_file(path)
    if expected_sha256 is not None:
        _validate_sha256(f"{label} SHA-256", expected_sha256)
        if actual_sha256 != expected_sha256:
            raise EvaluationEvidenceError(f"{label} SHA-256 mismatch")
    return {"path": str(path), "sha256": actual_sha256}


def _load_json_object(path: Path, *, label: str) -> dict[str, Any]:
    try:
        data = gzip.decompress(path.read_bytes()) if path.suffix == ".gz" else path.read_bytes()
        value = json.loads(data.decode("utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise EvaluationEvidenceError(f"cannot read {label}: {exc}") from exc
    if not isinstance(value, dict):
        raise EvaluationEvidenceError(f"{label} must be a JSON object")
    return value


def validate_scenario_contract(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != SCENARIO_FIELDS:
        raise EvaluationEvidenceError(
            "scenario contract must contain exactly scenario_id, scenario_overrides, "
            "command_schedule, duration_steps, num_envs, and seed"
        )
    _validate_identifier("scenario_id", value["scenario_id"])
    if not isinstance(value["scenario_overrides"], dict):
        raise EvaluationEvidenceError("scenario_overrides must be an object")
    for key, setting in value["scenario_overrides"].items():
        if key.startswith("evaluation."):
            from policy_evaluation_telemetry import ROA_CONTROL_MODES, DWAQ_CONTROL_MODES
            modes = {"evaluation.roa_mode": ROA_CONTROL_MODES,
                     "evaluation.dwaq_mode": DWAQ_CONTROL_MODES}
            if key not in modes or setting not in modes[key]:
                raise EvaluationEvidenceError("invalid evaluation controller or unknown evaluation option")
    if all(key in value["scenario_overrides"] for key in ("evaluation.roa_mode", "evaluation.dwaq_mode")):
        raise EvaluationEvidenceError("ROA and DWAQ diagnostic modes are mutually exclusive")
    if not isinstance(value["command_schedule"], list):
        raise EvaluationEvidenceError("command_schedule must be an array")
    for field in ("duration_steps", "num_envs"):
        field_value = value[field]
        if (
            isinstance(field_value, bool)
            or not isinstance(field_value, int)
            or field_value <= 0
        ):
            raise EvaluationEvidenceError(f"{field} must be a positive integer")
    if isinstance(value["seed"], bool) or not isinstance(value["seed"], int):
        raise EvaluationEvidenceError("seed must be an integer")

    previous_end = -1
    for index, segment in enumerate(value["command_schedule"]):
        if not isinstance(segment, dict) or set(segment) != {
            "start_step",
            "end_step",
            "command",
        }:
            raise EvaluationEvidenceError(
                f"command schedule segment {index} is invalid"
            )
        start = segment["start_step"]
        end = segment["end_step"]
        command = segment["command"]
        if (
            isinstance(start, bool)
            or not isinstance(start, int)
            or isinstance(end, bool)
            or not isinstance(end, int)
            or start != previous_end + 1
            or end < start
            or end >= value["duration_steps"]
        ):
            raise EvaluationEvidenceError(
                "command schedule must be ordered, contiguous, and within duration"
            )
        if (
            not isinstance(command, list)
            or len(command) != 3
            or any(
                isinstance(item, bool)
                or not isinstance(item, (int, float))
                or not math.isfinite(float(item))
                for item in command
            )
        ):
            raise EvaluationEvidenceError(
                "command schedule values must be finite [vx, vy, yaw_rate]"
            )
        previous_end = end
    if value["command_schedule"] and previous_end != value["duration_steps"] - 1:
        raise EvaluationEvidenceError(
            "command schedule must cover every evaluation step"
        )
    try:
        canonical_json(value)
    except (TypeError, ValueError) as exc:
        raise EvaluationEvidenceError(f"scenario contract is not finite JSON: {exc}") from exc
    return value


def build_scenario_contract(
    *,
    scenario_id: str,
    scenario_overrides_json: str,
    command_schedule_json: str,
    duration_steps: int,
    num_envs: int,
    seed: int,
) -> dict[str, Any]:
    try:
        scenario_overrides = json.loads(scenario_overrides_json)
    except json.JSONDecodeError as exc:
        raise EvaluationEvidenceError(
            f"invalid scenario_overrides_json at column {exc.colno}: {exc.msg}"
        ) from exc
    try:
        command_schedule = json.loads(command_schedule_json)
    except json.JSONDecodeError as exc:
        raise EvaluationEvidenceError(
            f"invalid command_schedule_json at column {exc.colno}: {exc.msg}"
        ) from exc
    return validate_scenario_contract(
        {
            "scenario_id": scenario_id,
            "scenario_overrides": scenario_overrides,
            "command_schedule": command_schedule,
            "duration_steps": duration_steps,
            "num_envs": num_envs,
            "seed": seed,
        }
    )


def scenario_sha256(contract: dict[str, Any]) -> str:
    validate_scenario_contract(contract)
    return sha256_bytes(canonical_json(contract).encode("utf-8"))


def expected_evaluation_paths(
    repo_root: Path,
    *,
    task: str,
    run_id: str,
    evaluation_id: str,
    batch_id: str | None = None,
) -> dict[str, Path]:
    _reject_unsafe_path(repo_root, label="repository root")
    _validate_identifier("task", task)
    _validate_identifier("run_id", run_id)
    _validate_identifier("evaluation_id", evaluation_id)
    evaluation_dir = (
        repo_root
        / "learnings"
        / "policy_tuning"
        / task
        / run_id
        / "evidence"
        / "play"
        / evaluation_id
    )
    if batch_id is not None:
        _validate_identifier("batch_id", batch_id)
        evaluation_dir = repo_root / "learnings" / "policy_tuning" / task / run_id / "evaluations" / batch_id / "raw" / evaluation_id
    return {
        "evaluation_dir": evaluation_dir,
        "result": evaluation_dir / "result.json",
        "telemetry": evaluation_dir / ("telemetry.json.gz" if batch_id else "telemetry.json"),
        "video": evaluation_dir / "video.mp4",
    }


def _require_exact_path(actual: Path, expected: Path, *, label: str) -> None:
    _reject_unsafe_path(actual, label=label)
    if actual != expected:
        raise EvaluationEvidenceError(
            f"{label} is outside the current run/evaluation evidence layout"
        )


def _require_new_targets(paths: dict[str, Path]) -> None:
    for label in ("result", "telemetry", "video"):
        path = paths[label]
        _reject_unsafe_path(path, label=f"{label} target")
        if path.exists() or path.is_symlink():
            raise EvaluationEvidenceError(f"{label} target already exists: {path}")


def _load_bound_run_identity(
    path: Path,
    *,
    expected_file_sha256: str,
    repo_root: Path,
    task: str,
    run_id: str,
    seed: int,
    scenario_contract: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, str]]:
    reference = _require_regular_file(
        path,
        label="run identity",
        expected_sha256=expected_file_sha256,
    )
    identity = _load_json_object(path, label="run identity")
    try:
        require_source_path(path, repo_root / "learnings" / "policy_tuning" / task / run_id, "context")
        if identity.get("version") == 2:
            from capture_run_identity import validate_run_identity
            validate_run_identity(identity)
    except ValueError as exc:
        raise EvaluationEvidenceError(str(exc)) from exc
    payload = {key: value for key, value in identity.items() if key != "identity_sha256"}
    internal_sha256 = sha256_bytes(canonical_json(payload).encode("utf-8"))
    if identity.get("identity_sha256") != internal_sha256:
        raise EvaluationEvidenceError("run identity internal SHA-256 mismatch")
    for field, expected in (("task", task), ("run_id", run_id), ("seed", seed)):
        if identity.get(field) != expected:
            raise EvaluationEvidenceError(f"run identity {field} mismatch")
    source = identity.get("source")
    if not isinstance(source, dict) or source.get("repository_root") != str(repo_root):
        raise EvaluationEvidenceError("run identity repository root mismatch")
    if identity["version"] == 1:
        evaluation = identity.get("evaluation_scenario")
        if not isinstance(evaluation, dict):
            raise EvaluationEvidenceError("run identity evaluation_scenario is missing")
        identity_contract = validate_scenario_contract(evaluation.get("contract"))
        expected_scenario_sha256 = scenario_sha256(identity_contract)
        if evaluation.get("sha256") != expected_scenario_sha256:
            raise EvaluationEvidenceError("run identity scenario SHA-256 mismatch")
        if identity_contract != scenario_contract:
            raise EvaluationEvidenceError("run identity scenario contract mismatch")
    return identity, {
        "path": reference["path"],
        "file_sha256": reference["sha256"],
        "identity_sha256": internal_sha256,
    }


@dataclass(frozen=True)
class EvaluationPlan:
    repo_root: Path
    task: str
    run_id: str
    evaluation_id: str
    result_path: Path
    telemetry_path: Path | None
    video_path: Path | None
    canonical_paths: dict[str, Path]
    checkpoint: dict[str, str]
    artifact: dict[str, str]
    artifact_kind: str
    run_identity: dict[str, str]
    scenario_contract: dict[str, Any]
    scenario_sha256: str
    batch_id: str | None = None
    effective_config: dict | None = None
    scenario_evidence: dict | None = None


def preflight_evaluation(
    *,
    repo_root: Path,
    task: str,
    run_id: str,
    evaluation_id: str,
    result_path: Path,
    telemetry_path: Path | None,
    video_path: Path | None,
    checkpoint_path: Path,
    checkpoint_sha256: str,
    artifact_kind: str,
    artifact_path: Path,
    artifact_sha256: str,
    run_identity_path: Path,
    run_identity_file_sha256: str,
    scenario_contract: dict[str, Any],
    batch_id: str | None = None,
    effective_config: dict | None = None,
    scenario_evidence: dict | None = None,
) -> EvaluationPlan:
    if artifact_kind not in {"native", "jit", "onnx"}:
        raise EvaluationEvidenceError("artifact_kind must be native, jit, or onnx")
    repo_root = repo_root.absolute()
    canonical_paths = expected_evaluation_paths(
        repo_root,
        task=task,
        run_id=run_id,
        evaluation_id=evaluation_id,
        batch_id=batch_id,
    )
    evaluation_dir = canonical_paths["evaluation_dir"]
    _reject_unsafe_path(evaluation_dir, label="evaluation directory")
    if not evaluation_dir.is_dir():
        raise EvaluationEvidenceError(
            "evaluation directory must be prepared by prepare_evidence_layout.py"
        )
    _require_exact_path(result_path, canonical_paths["result"], label="result_path")
    if telemetry_path is not None:
        _require_exact_path(
            telemetry_path,
            canonical_paths["telemetry"],
            label="telemetry_path",
        )
    if video_path is not None:
        _require_exact_path(video_path, canonical_paths["video"], label="video_path")
    _require_new_targets(canonical_paths)
    if batch_id is not None and (evaluation_dir / ".attempt-used").exists():
        raise EvaluationEvidenceError("attempt ID already used")

    checkpoint = _require_regular_file(
        checkpoint_path,
        label="checkpoint",
        expected_sha256=checkpoint_sha256,
    )
    artifact = _require_regular_file(
        artifact_path,
        label="artifact",
        expected_sha256=artifact_sha256,
    )
    scenario_contract = validate_scenario_contract(scenario_contract)
    identity, run_identity = _load_bound_run_identity(
        run_identity_path,
        expected_file_sha256=run_identity_file_sha256,
        repo_root=repo_root,
        task=task,
        run_id=run_id,
        seed=scenario_contract["seed"],
        scenario_contract=scenario_contract,
    )
    if batch_id is not None:
        try:
            validate_provenance(identity, effective_config, scenario_evidence, scenario_contract, live=True)
        except (ValueError, OSError, KeyError, TypeError) as exc:
            raise EvaluationEvidenceError(str(exc)) from exc
    elif identity["version"] != 1 or effective_config is not None or scenario_evidence is not None:
        raise EvaluationEvidenceError("new provenance requires a batch_id")
    return EvaluationPlan(
        repo_root=repo_root,
        task=task,
        run_id=run_id,
        evaluation_id=evaluation_id,
        result_path=result_path,
        telemetry_path=telemetry_path,
        video_path=video_path,
        canonical_paths=canonical_paths,
        checkpoint=checkpoint,
        artifact=artifact,
        artifact_kind=artifact_kind,
        run_identity=run_identity,
        scenario_contract=scenario_contract,
        scenario_sha256=scenario_sha256(scenario_contract),
        batch_id=batch_id,
        effective_config=effective_config,
        scenario_evidence=scenario_evidence,
    )


def _write_new_json(path: Path, value: dict[str, Any]) -> None:
    encoded = json.dumps(
        value,
        indent=2,
        sort_keys=True,
        ensure_ascii=False,
        allow_nan=False,
    ) + "\n"
    with path.open("x", encoding="utf-8") as stream:
        stream.write(encoded)


class EvaluationPublisher:
    """Claim one evaluation directory and publish result last without overwrite."""

    def __init__(self, plan: EvaluationPlan) -> None:
        self.plan = plan
        self.evaluation_dir = plan.canonical_paths["evaluation_dir"]
        self.claim_path = self.evaluation_dir / ".publish-claim"
        self.attempt_dir = self.evaluation_dir / ".attempt"
        self.video_work_path = self.attempt_dir / "video.mp4"
        self._entered = False
        self._published = False
        self._claim_identity: tuple[int, int] | None = None
        self._attempt_identity: tuple[int, int] | None = None

    def __enter__(self) -> "EvaluationPublisher":
        _require_new_targets(self.plan.canonical_paths)
        try:
            with self.claim_path.open("x", encoding="utf-8") as stream:
                stream.write(self.plan.evaluation_id + "\n")
        except FileExistsError as exc:
            raise EvaluationEvidenceError(
                f"evaluation publication is already claimed: {self.claim_path}"
            ) from exc
        claim_stat = self.claim_path.stat(follow_symlinks=False)
        self._claim_identity = (claim_stat.st_dev, claim_stat.st_ino)
        try:
            if self.plan.batch_id is not None:
                with (self.evaluation_dir / ".attempt-used").open("x") as stream:
                    stream.write(self.plan.evaluation_id + "\n")
            self.attempt_dir.mkdir()
        except OSError as exc:
            if self._still_owned(self.claim_path, self._claim_identity):
                self.claim_path.unlink()
            self._claim_identity = None
            raise EvaluationEvidenceError(
                f"cannot create exclusive evaluation attempt: {exc}"
            ) from exc
        attempt_stat = self.attempt_dir.stat(follow_symlinks=False)
        self._attempt_identity = (attempt_stat.st_dev, attempt_stat.st_ino)
        self._entered = True
        return self

    @staticmethod
    def _still_owned(path: Path, identity: tuple[int, int] | None) -> bool:
        if identity is None:
            return False
        try:
            stat_result = path.stat(follow_symlinks=False)
        except FileNotFoundError:
            return False
        return (stat_result.st_dev, stat_result.st_ino) == identity

    def _cleanup_owned(self) -> None:
        if self._still_owned(self.attempt_dir, self._attempt_identity):
            shutil.rmtree(self.attempt_dir)
        if self._still_owned(self.claim_path, self._claim_identity):
            self.claim_path.unlink()
        self._attempt_identity = None
        self._claim_identity = None

    def close(self) -> None:
        """Release only this publisher's temporary claim and attempt data."""
        if self._entered:
            self._cleanup_owned()
            self._entered = False

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> None:
        self.close()

    def publish(
        self,
        result: dict[str, Any],
        *,
        telemetry: dict[str, Any] | None,
        video_source: Path | None,
    ) -> dict[str, Any]:
        if not self._entered or self._published:
            raise EvaluationEvidenceError("evaluation publisher is not active")
        if (telemetry is None) != (self.plan.telemetry_path is None):
            raise EvaluationEvidenceError("telemetry payload does not match telemetry_path")
        if (video_source is None) != (self.plan.video_path is None):
            raise EvaluationEvidenceError("video payload does not match video_path")
        _require_new_targets(self.plan.canonical_paths)

        telemetry_work = self.attempt_dir / "telemetry.json"
        result_work = self.attempt_dir / "result.json"
        telemetry_reference = None
        if telemetry is not None:
            if self.plan.batch_id is not None:
                encoded = (json.dumps(telemetry, sort_keys=True, ensure_ascii=False, allow_nan=False) + "\n").encode("utf-8")
                with telemetry_work.open("xb") as stream:
                    stream.write(gzip.compress(encoded, mtime=0))
            else:
                _write_new_json(telemetry_work, telemetry)
            telemetry_reference = {
                "path": str(self.plan.telemetry_path),
                "sha256": sha256_file(telemetry_work),
            }
        video_reference = None
        if video_source is not None:
            if video_source != self.video_work_path:
                raise EvaluationEvidenceError("video source is outside the evaluation attempt")
            video_work = _require_regular_file(video_source, label="attempt video")
            video_reference = {
                "path": str(self.plan.video_path),
                "sha256": video_work["sha256"],
            }

        published_result = dict(result)
        published_result["result_path"] = str(self.plan.result_path)
        published_result["outputs"] = {
            "telemetry": telemetry_reference,
            "video": video_reference,
        }
        _write_new_json(result_work, published_result)

        sources_and_targets: list[tuple[Path, Path]] = []
        if video_source is not None:
            assert self.plan.video_path is not None
            sources_and_targets.append((video_source, self.plan.video_path))
        if telemetry is not None:
            assert self.plan.telemetry_path is not None
            sources_and_targets.append((telemetry_work, self.plan.telemetry_path))
        created_targets: list[Path] = []
        try:
            for source, target in sources_and_targets:
                os.link(source, target, follow_symlinks=False)
                created_targets.append(target)
            validate_evaluation_bundle(
                result_work,
                canonical_result_path=self.plan.result_path,
            )
            os.link(result_work, self.plan.result_path, follow_symlinks=False)
            created_targets.append(self.plan.result_path)
            validate_evaluation_bundle(self.plan.result_path)
        except (OSError, EvaluationEvidenceError) as exc:
            for target in reversed(created_targets):
                target.unlink(missing_ok=True)
            raise EvaluationEvidenceError(
                f"exclusive evaluation publication failed: {exc}"
            ) from exc
        self._published = True
        return published_result


def close_evaluation_resources(
    publisher: EvaluationPublisher,
    simulation_app: Any,
) -> None:
    """Release publication state before shutting down Isaac Sim."""
    try:
        publisher.close()
    finally:
        simulation_app.close()


def _validate_reference(value: Any, *, label: str) -> dict[str, str]:
    if not isinstance(value, dict) or set(value) != {"path", "sha256"}:
        raise EvaluationEvidenceError(f"{label} reference is invalid")
    path_value = value.get("path")
    if not isinstance(path_value, str):
        raise EvaluationEvidenceError(f"{label} path is invalid")
    reference = _require_regular_file(
        Path(path_value),
        label=label,
        expected_sha256=value.get("sha256"),
    )
    return reference


def validate_evaluation_bundle(
    result_path: Path,
    *,
    canonical_result_path: Path | None = None,
) -> dict[str, Any]:
    """Revalidate a final bundle or a private result before final publication."""
    result_reference = _require_regular_file(result_path, label="evaluation result")
    result = _load_json_object(result_path, label="evaluation result")
    if result.get("version") not in {2, 3} or result.get("status") != "completed":
        raise EvaluationEvidenceError("evaluation result must be completed version 2 or 3")
    if result["version"] == 3 and result.get("layout_version") != 2:
        raise EvaluationEvidenceError("new result requires layout_version 2")
    evaluation = result.get("evaluation")
    inputs = result.get("inputs")
    outputs = result.get("outputs")
    if not isinstance(evaluation, dict) or not isinstance(inputs, dict):
        raise EvaluationEvidenceError("evaluation result binding is incomplete")
    if not isinstance(outputs, dict) or set(outputs) != {"telemetry", "video"}:
        raise EvaluationEvidenceError("evaluation result outputs are incomplete")
    task = _validate_identifier("result task", evaluation.get("task"))
    run_id = _validate_identifier("result run_id", evaluation.get("run_id"))
    evaluation_id = _validate_identifier(
        "result evaluation_id", evaluation.get("evaluation_id")
    )
    _validate_identifier("result candidate_id", evaluation.get("candidate_id"))
    _validate_identifier("result runner", evaluation.get("runner"))
    resource_mode = inputs.get("resource_mode")
    if not isinstance(resource_mode, dict):
        raise EvaluationEvidenceError("result resource mode is missing")
    for field in (
        "training_overlap",
        "idle_gpu_required",
        "video_requested",
        "telemetry_requested",
    ):
        if not isinstance(resource_mode.get(field), bool):
            raise EvaluationEvidenceError(f"result resource mode {field} is invalid")
    run_identity = inputs.get("run_identity")
    if not isinstance(run_identity, dict):
        raise EvaluationEvidenceError("result run identity reference is missing")
    run_identity_path = run_identity.get("path")
    if not isinstance(run_identity_path, str):
        raise EvaluationEvidenceError("result run identity path is invalid")
    identity_document = _load_json_object(
        Path(run_identity_path), label="result run identity"
    )
    source = identity_document.get("source")
    if not isinstance(source, dict) or not isinstance(source.get("repository_root"), str):
        raise EvaluationEvidenceError("result run identity repository root is missing")
    repo_root = Path(source["repository_root"])
    expected_paths = expected_evaluation_paths(
        repo_root,
        task=task,
        run_id=run_id,
        evaluation_id=evaluation_id,
        batch_id=evaluation.get("batch_id") if result["version"] == 3 else None,
    )
    declared_result_path = canonical_result_path or result_path
    _require_exact_path(
        declared_result_path,
        expected_paths["result"],
        label="result_path",
    )
    if result.get("result_path") != str(declared_result_path):
        raise EvaluationEvidenceError("embedded result_path mismatch")

    scenario = inputs.get("scenario")
    if not isinstance(scenario, dict) or set(scenario) != {"contract", "sha256"}:
        raise EvaluationEvidenceError("result scenario binding is invalid")
    scenario_contract = validate_scenario_contract(scenario["contract"])
    if scenario["sha256"] != scenario_sha256(scenario_contract):
        raise EvaluationEvidenceError("result scenario SHA-256 mismatch")
    loaded_identity, bound_identity = _load_bound_run_identity(
        Path(run_identity_path),
        expected_file_sha256=run_identity.get("file_sha256"),
        repo_root=repo_root,
        task=task,
        run_id=run_id,
        seed=scenario_contract["seed"],
        scenario_contract=scenario_contract,
    )
    if run_identity.get("identity_sha256") != bound_identity["identity_sha256"]:
        raise EvaluationEvidenceError("result run identity SHA-256 mismatch")
    if result["version"] == 3:
        _validate_identifier("batch_id", evaluation.get("batch_id"))
        if loaded_identity["runner"] != evaluation["runner"]:
            raise EvaluationEvidenceError("result runner mismatch")
        try:
            validate_provenance(loaded_identity, inputs.get("effective_config"), inputs.get("scenario_evidence"), scenario_contract)
        except (ValueError, OSError, KeyError, TypeError) as exc:
            raise EvaluationEvidenceError(str(exc)) from exc
    elif loaded_identity["version"] != 1:
        raise EvaluationEvidenceError("legacy result requires legacy identity")

    checkpoint = _validate_reference(inputs.get("checkpoint"), label="result checkpoint")
    artifact = inputs.get("artifact")
    if not isinstance(artifact, dict) or set(artifact) != {"kind", "path", "sha256"}:
        raise EvaluationEvidenceError("result artifact reference is invalid")
    artifact_reference = _validate_reference(
        {"path": artifact["path"], "sha256": artifact["sha256"]},
        label="result artifact",
    )

    output_references: dict[str, dict[str, str] | None] = {}
    for label in ("telemetry", "video"):
        value = outputs[label]
        if value is None:
            output_references[label] = None
            continue
        reference = _validate_reference(value, label=f"result {label}")
        _require_exact_path(
            Path(reference["path"]),
            expected_paths[label],
            label=f"result {label}",
        )
        output_references[label] = reference
    if resource_mode["telemetry_requested"] != (
        output_references["telemetry"] is not None
    ):
        raise EvaluationEvidenceError("telemetry resource mode/output mismatch")
    if resource_mode["video_requested"] != (
        output_references["video"] is not None
    ):
        raise EvaluationEvidenceError("video resource mode/output mismatch")
    telemetry_reference = output_references["telemetry"]
    if telemetry_reference is not None:
        telemetry = _load_json_object(
            Path(telemetry_reference["path"]), label="evaluation telemetry"
        )
        if result["version"] == 3 and telemetry.get("version") != 4:
            raise EvaluationEvidenceError("new result requires telemetry version 4")
        if telemetry.get("evaluation") != evaluation:
            raise EvaluationEvidenceError("telemetry evaluation binding mismatch")
        if telemetry.get("inputs") != inputs:
            raise EvaluationEvidenceError("telemetry input binding mismatch")

    roa_mode = scenario_contract["scenario_overrides"].get("evaluation.roa_mode")
    if roa_mode is not None:
        from policy_evaluation_telemetry import roa_diagnostic_signals
        if evaluation["runner"] != "OnPolicyRunnerROA" or artifact["kind"] != "native":
            raise EvaluationEvidenceError("ROA diagnostics require native OnPolicyRunnerROA")
        if telemetry_reference is None:
            raise EvaluationEvidenceError("ROA diagnostics require telemetry")
        diagnostic = result.get("roa_diagnostics", {})
        if (diagnostic.get("controller") != roa_mode
                or diagnostic.get("sampling_phase") != "pre_action"
                or diagnostic.get("velocity_units") != "m/s"
                or telemetry.get("roa_diagnostics") != diagnostic):
            raise EvaluationEvidenceError("ROA diagnostic mode/units/timing binding mismatch")
        scales = diagnostic.get("velocity_observation_scale")
        if (not isinstance(scales, list) or len(scales) not in (1, 3)
                or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) or x <= 0 for x in scales)):
            raise EvaluationEvidenceError("invalid ROA velocity observation scale")
        required = set(roa_diagnostic_signals(roa_mode))
        if not required.issubset(telemetry.get("required_signals", [])):
            raise EvaluationEvidenceError("ROA diagnostic signals must be required")
        for sample in telemetry.get("samples", []):
            for name in required:
                values = sample.get(name)
                if not isinstance(values, list) or not values or any(not isinstance(x, (int, float)) or isinstance(x, bool) or not math.isfinite(x) for x in values):
                    raise EvaluationEvidenceError(f"invalid or missing ROA signal {name}")
            if sample["action"] != sample[f"roa_{roa_mode}_action"]:
                raise EvaluationEvidenceError("executed action differs from selected ROA branch")
        expected = len(range(0, scenario_contract["duration_steps"], resource_mode["telemetry_stride"]))
        if len(telemetry.get("samples", [])) != expected:
            raise EvaluationEvidenceError("ROA diagnostic sample count mismatch")
        if any(not telemetry.get("signal_status", {}).get(name, {}).get("complete") for name in required):
            raise EvaluationEvidenceError("incomplete ROA diagnostic signals")

    dwaq_mode = scenario_contract["scenario_overrides"].get("evaluation.dwaq_mode")
    if dwaq_mode is not None:
        from policy_evaluation_telemetry import DWAQ_DIAGNOSTIC_SIGNALS
        if evaluation["runner"] != "OnPolicyRunnerDwaq" or artifact["kind"] != "native":
            raise EvaluationEvidenceError("DWAQ diagnostics require native OnPolicyRunnerDwaq")
        if telemetry_reference is None:
            raise EvaluationEvidenceError("DWAQ diagnostics require telemetry")
        diagnostic = result.get("dwaq_diagnostics", {})
        if (diagnostic.get("controller") != dwaq_mode
                or diagnostic.get("sampling_phase") != "pre_action"
                or diagnostic.get("velocity_units") != "m/s"
                or telemetry.get("dwaq_diagnostics") != diagnostic):
            raise EvaluationEvidenceError("DWAQ diagnostic mode/units/timing binding mismatch")
        scales = diagnostic.get("velocity_observation_scale")
        if (not isinstance(scales, list) or len(scales) not in (1, 3)
                or any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) or x <= 0 for x in scales)):
            raise EvaluationEvidenceError("invalid DWAQ velocity observation scale")
        required = set(DWAQ_DIAGNOSTIC_SIGNALS)
        if not required.issubset(telemetry.get("required_signals", [])):
            raise EvaluationEvidenceError("DWAQ diagnostic signals must be required")
        for sample in telemetry.get("samples", []):
            for name in required:
                values = sample.get(name)
                if not isinstance(values, list) or not values or any(not isinstance(x, (int, float)) or isinstance(x, bool) or not math.isfinite(x) for x in values):
                    raise EvaluationEvidenceError(f"invalid or missing DWAQ signal {name}")
            if sample["action"] != sample[f"dwaq_{dwaq_mode}_action"]:
                raise EvaluationEvidenceError("executed action differs from selected DWAQ branch")
        expected = len(range(0, scenario_contract["duration_steps"], resource_mode["telemetry_stride"]))
        if len(telemetry.get("samples", [])) != expected:
            raise EvaluationEvidenceError("DWAQ diagnostic sample count mismatch")
        if any(not telemetry.get("signal_status", {}).get(name, {}).get("complete") for name in required):
            raise EvaluationEvidenceError("incomplete DWAQ diagnostic signals")

    return {
        "status": "valid",
        "result": result_reference,
        "checkpoint": checkpoint,
        "artifact": artifact_reference,
        "run_identity": bound_identity,
        "scenario_sha256": scenario["sha256"],
        "outputs": output_references,
    }

